story=[]
def p(s,style='body'): story.append(Paragraph(s,styles[style]))
def sub(s): p(s,'sub')
def page(title,kicker):
    while story and isinstance(story[-1],Spacer): story.pop()
    if story: story.append(PageBreak())
    p(kicker.upper(),'small'); p(title,'h')
def table(headers,rows,widths):
    data=[[Paragraph(escape(str(c)),styles['head']) for c in headers]]
    data += [[Paragraph(escape(str(c)),styles['cell']) for c in row] for row in rows]
    t=Table(data,colWidths=widths,hAlign='LEFT',repeatRows=1)
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),TEAL),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,LIGHT]),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),8),('RIGHTPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7),('LINEBELOW',(0,-1),(-1,-1),.5,colors.HexColor('#CADCD5'))]))
    story.append(t);story.append(Spacer(1,10))
def note(s):
    t=Table([[Paragraph(s,styles['body'])]],colWidths=[491])
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),LIGHT),('BOX',(0,0),(-1,-1),.5,colors.HexColor('#C7DFD5')),('LEFTPADDING',(0,0),(-1,-1),12),('RIGHTPADDING',(0,0),(-1,-1),12),('TOPPADDING',(0,0),(-1,-1),10),('BOTTOMPADDING',(0,0),(-1,-1),5)]))
